/** Bung manifest thành mảng { path, size } đầy đủ. */
function listAssets() {
  const out = [];
  for (const dir of Object.keys(MANIFEST)) {
    for (const entry of MANIFEST[dir].split(' ')) {
      const i = entry.lastIndexOf(':');
      out.push({ path: `${dir}/${entry.slice(0, i)}`, size: +entry.slice(i + 1) });
    }
  }
  return out;
}

/** Tra kích thước một đường dẫn logic; trả về -1 nếu không có trong bảng kê. */
function assetSize(logicalPath) {
  const i = logicalPath.lastIndexOf('/');
  const group = MANIFEST[logicalPath.slice(0, i)];
  if (!group) return -1;
  const name = logicalPath.slice(i + 1);
  for (const entry of group.split(' ')) {
    if (entry.startsWith(name + ':')) return +entry.slice(name.length + 1);
  }
  return -1;
}

/* ─────────────── SỬA LỆCH HOA-THƯỜNG TRONG TÊN FILE ───────────────
   items.json của MU ghi "Item/Wing08.glb" và "Item/sword20.glb", còn trên đĩa
   là "wing08.glb" và "Sword20.glb". Client MU gốc chạy trên Windows — hệ tệp
   ở đó không phân biệt hoa thường nên không ai để ý. Trên Linux, trên máy chủ
   tĩnh và trong zip thì lệch một chữ là 404.

   Đo được: cánh cấp 3 và kiếm Archangel đều 404 vì đúng lý do này, mà không
   có lỗi nào hiện ra — Babylon nuốt lỗi nạp model.

   Bảng kê đã có sẵn TÊN THẬT của cả 11.996 file, nên dùng luôn nó làm bảng
   tra. Chỉ dựng chỉ mục cho thư mục nào thực sự bị hỏi tới, và chỉ khi tên
   đúng y nguyên không có — đường dẫn đúng thì không tốn gì. */

const chiMucThuMuc = new Map();

/**
 * Trả về đường dẫn logic với ĐÚNG hoa thường như trên đĩa.
 * Không tìm thấy thì trả về nguyên đường dẫn đưa vào.
 */
function suaHoaThuong(logicalPath) {
  const i = logicalPath.lastIndexOf('/');
  if (i < 0) return logicalPath;

  const dir = logicalPath.slice(0, i);
  const name = logicalPath.slice(i + 1);
  const group = MANIFEST[dir];
  if (!group) return logicalPath;

  // Tên đúng y nguyên thì thôi, khỏi dựng chỉ mục.
  if (group.includes(name + ':')) return logicalPath;

  let idx = chiMucThuMuc.get(dir);
  if (!idx) {
    idx = new Map();
    for (const entry of group.split(' ')) {
      const j = entry.lastIndexOf(':');
      const ten = entry.slice(0, j);
      idx.set(ten.toLowerCase(), ten);
    }
    chiMucThuMuc.set(dir, idx);
  }

  const that = idx.get(name.toLowerCase());
  return that ? `${dir}/${that}` : logicalPath;
}

/* js/zip-store.js */
// Đọc asset thẳng từ một file .zip nằm trong img/.
//
// VÌ SAO CẦN: JSAnywhere trên iOS chỉ cho nạp TỪNG FILE vào img/, không nạp cả
// thư mục. Bộ asset có 11.996 file — nạp tay là bất khả thi. Một file zip thì
// nạp đúng một lần.
//
// VÌ SAO KHÔNG BUNG HẾT RA BỘ NHỚ: zip 288 MB, giải nén 630 MB. Giữ chừng ấy
// trong RAM là Safari giết tab. Cách làm ở đây:
//
//   1. fetch() rồi lấy .blob() — KHÔNG lấy .arrayBuffer(). Safari đẩy Blob lớn
//      xuống đĩa, RAM gần như không tốn gì.
//   2. Đọc bảng mục lục ở CUỐI file zip → biết mỗi file nằm ở byte thứ mấy.
//   3. Cần file nào thì blob.slice() đúng khúc đó rồi bung.
//
// Nhờ vậy không cần server hỗ trợ HTTP Range: chỉ một lần tải, sau đó đọc đĩa.
//
// BUNG NÉN KHÔNG CẦN THƯ VIỆN: DecompressionStream('deflate-raw') là API sẵn
// của trình duyệt (Safari 16.4+, iOS 16.4+). Mục trong zip nén bằng raw deflate
// nên dùng thẳng được, khỏi nhét fflate hay pako vào bundle.

const SIG_EOCD = 0x06054b50;   // End Of Central Directory
const SIG_CD = 0x02014b50;     // một mục trong bảng mục lục
const SIG_LOCAL = 0x04034b50;  // đầu mỗi file trong zip

// EOCD dài 22 byte, phần chú thích tối đa 65535 → chỉ cần dò 64 KB cuối.
const EOCD_SEARCH = 66000;

/** Đọc một khúc Blob ra DataView. */
async function view(blob, start, end) {
  const buf = await blob.slice(start, end).arrayBuffer();
  return new DataView(buf);
}

/**
 * Mở một file zip và đọc bảng mục lục.
 * Trả về đối tượng có .has(), .bytes(), .url(), .list().
 */
async function openZip(blob) {
  const size = blob.size;

  // ---- tìm EOCD bằng cách dò ngược 64 KB cuối
  const tailStart = Math.max(0, size - EOCD_SEARCH);
  const tail = await view(blob, tailStart, size);

  let eocd = -1;
  for (let i = tail.byteLength - 22; i >= 0; i--) {
    if (tail.getUint32(i, true) === SIG_EOCD) {
      eocd = i;
      break;
    }
  }
  if (eocd < 0) throw new Error('Không phải file zip hợp lệ: thiếu EOCD');

  const count = tail.getUint16(eocd + 10, true);
  const cdSize = tail.getUint32(eocd + 12, true);
  const cdOffset = tail.getUint32(eocd + 16, true);

  // Zip64 dùng khi quá 65535 mục hoặc quá 4 GB. Bộ asset 12.340 mục / 630 MB
  // chưa chạm ngưỡng, nhưng cứ báo rõ thay vì đọc bậy ra số rác.
  if (cdOffset === 0xffffffff || count === 0xffff) {
    throw new Error('Zip64 chưa hỗ trợ — nén lại bằng zip thường');
  }

  // ---- đọc cả bảng mục lục một lần (khoảng 1 MB cho 12 nghìn mục)
  const cd = await view(blob, cdOffset, cdOffset + cdSize);
  const utf8 = new TextDecoder('utf-8');

  const entries = new Map();
  let p = 0;
  for (let i = 0; i < count; i++) {
    if (cd.getUint32(p, true) !== SIG_CD) break;

    const method = cd.getUint16(p + 10, true);
    const compSize = cd.getUint32(p + 20, true);
    const rawSize = cd.getUint32(p + 24, true);
    const nameLen = cd.getUint16(p + 28, true);
    const extraLen = cd.getUint16(p + 30, true);
    const cmtLen = cd.getUint16(p + 32, true);
    const localAt = cd.getUint32(p + 42, true);

    const name = utf8.decode(
      new Uint8Array(cd.buffer, cd.byteOffset + p + 46, nameLen)
    );

    p += 46 + nameLen + extraLen + cmtLen;

    // Bỏ thư mục và rác macOS tự nhét vào khi nén.
    if (name.endsWith('/')) continue;
    if (name.startsWith('__MACOSX/') || name.endsWith('.DS_Store')) continue;

    entries.set(name, { method, compSize, rawSize, localAt });
  }

  if (entries.size === 0) throw new Error('Zip rỗng hoặc không đọc được mục nào');

  /**
   * Tiền tố thư mục bên trong zip — tự dò, không bắt người dùng nén đúng kiểu.
   * Nén từ thư mục public/ thì mục là "game-assets/World1/…", nén cả thư mục
   * cha thì thành "public/game-assets/…" hoặc "engine/public/game-assets/…".
   * Lấy một file chắc chắn có rồi cắt ngược ra tiền tố.
   */
  const MOC = 'game-assets/World1/EncTerrain1.map';
  let prefix = '';
  for (const name of entries.keys()) {
    if (name === MOC) { prefix = ''; break; }
    if (name.endsWith('/' + MOC)) {
      prefix = name.slice(0, name.length - MOC.length);
      break;
    }
  }

  return {
    /** Số mục đọc được. */
    get count() {
      return entries.size;
    },

    /** Tiền tố đã dò được ('' nếu zip nén từ đúng thư mục public/). */
    get prefix() {
      return prefix;
    },

    /** Đường dẫn logic có trong zip không. */
    has(logicalPath) {
      return entries.has(prefix + logicalPath);
    },

    /** Danh sách mọi mục (đã bỏ tiền tố). */
    list() {
      const out = [];
      for (const k of entries.keys()) {
        out.push(prefix && k.startsWith(prefix) ? k.slice(prefix.length) : k);
      }
      return out;
    },

    /** Lấy nội dung một file ra Blob. */
    async blob(logicalPath) {
      const e = entries.get(prefix + logicalPath);
      if (!e) return null;

      // Trường extra của đầu file CÓ THỂ khác trường extra trong bảng mục lục,
      // nên phải đọc lại đầu file mới biết dữ liệu bắt đầu ở đâu.
      const lh = await view(blob, e.localAt, e.localAt + 30);
      if (lh.getUint32(0, true) !== SIG_LOCAL) {
        throw new Error(`Hỏng cấu trúc zip ở ${logicalPath}`);
      }
      const dataAt =
        e.localAt + 30 + lh.getUint16(26, true) + lh.getUint16(28, true);

      const raw = blob.slice(dataAt, dataAt + e.compSize);

      if (e.method === 0) return raw;              // lưu thẳng, khỏi bung
      if (e.method !== 8) {
        throw new Error(`Kiểu nén ${e.method} chưa hỗ trợ (${logicalPath})`);
      }

      const out = raw.stream().pipeThrough(new DecompressionStream('deflate-raw'));
      return await new Response(out).blob();
    },
  };
}

/** Trình duyệt có bung được deflate không. Thiếu là hỏng ngay từ đầu. */
function zipSupported() {
  return typeof DecompressionStream === 'function';
}

/* js/zip-remote.js */
// Đọc asset thẳng từ một file .zip nằm TRÊN MẠNG, bằng HTTP Range.
//
// Khác gì zip-store.js: bản kia nhận một Blob đã tải về đủ (đọc đĩa, không ra
// mạng). Bản này không tải cả file — nó chỉ xin đúng khúc byte đang cần.
//
// VÌ SAO LÀM ĐƯỢC: zip là định dạng đọc-ngược. Bảng mục lục nằm ở CUỐI file và
// ghi rõ từng mục bắt đầu ở byte thứ mấy, dài bao nhiêu. Có bảng ấy là nhảy
// thẳng tới khúc cần, khỏi đụng phần còn lại.
//
// SỐ LIỆU THẬT của bộ đang dùng:
//   – zip 275 MB, 12.340 mục, nén kiểu "store" (lưu thẳng, không nén)
//   – bảng mục lục khoảng 1,2 MB
//   ⇒ khởi động tốn ~1,3 MB thay vì 275 MB. Mỗi asset sau đó tốn đúng cỡ nó.
//
// ĐIỀU KIỆN MÁY CHỦ — thiếu một trong hai là không chạy:
//   1. accept-ranges: bytes          (cho xin từng khúc)
//   2. access-control-allow-origin   (cho trang khác miền đọc)
// Máy chủ hiện dùng có đủ cả hai; nếu đổi chỗ chứa thì phải kiểm lại.
//
// CẢNH BÁO THẲNG: file này ĐI RA MẠNG. Đó là ngoại lệ do chủ dự án yêu cầu,
// ngược với quy tắc 4 trong CLAUDE.md. Địa chỉ không nhúng trong mã — nó nằm ở
// thẻ <meta name="mu-zip-url"> đầu index.html, sửa và xoá được bằng mắt thường.

/* Cùng bốn hằng như zip-store.js nhưng đặt tên riêng: bộ dựng gộp mọi module
   vào MỘT phạm vi, tên trùng là hỏng build. Hậu tố XA = đọc từ xa. */
const SIG_EOCD_XA = 0x06054b50;
const SIG_CD_XA = 0x02014b50;
const SIG_LOCAL_XA = 0x04034b50;

const EOCD_SEARCH_XA = 66000;

/* Trường extra của đầu mỗi file hiếm khi quá vài chục byte. Xin dư 256 byte để
   gộp "đọc đầu file" và "đọc dữ liệu" vào MỘT yêu cầu thay vì hai — 12 nghìn
   file mà mỗi file hai lượt thì số lượt gọi tăng gấp đôi vô ích. */
const DU_DAU = 256;

/** Xin một khúc byte. Trả ArrayBuffer. */
async function khuc(url, start, end) {
  const r = await fetch(url, { headers: { Range: `bytes=${start}-${end - 1}` } });
  if (!r.ok) throw new Error(`Range ${start}-${end} trả HTTP ${r.status}`);
  /* 206 là "đã cắt đúng khúc". 200 nghĩa là máy chủ LỜ ĐI Range và gửi cả
     file — phải biết để báo, không thì đọc nhầm offset ra dữ liệu rác. */
  if (r.status !== 206) {
    throw new Error('Máy chủ không hỗ trợ HTTP Range (trả 200 thay vì 206)');
  }
  return r.arrayBuffer();
}

/**
 * Kích thước file zip, hỏi bằng HEAD.
 *
 * HAI CÁCH TÔI THỬ TRƯỚC ĐỀU HỎNG, ghi lại để đừng ai làm lại:
 *
 *   1. GET `bytes=0-0` rồi đọc header `content-range`.
 *      Bằng curl thì ra số. Trong trình duyệt thì LUÔN null: khác miền thì
 *      JavaScript chỉ đọc được mấy header trong danh sách an toàn của CORS,
 *      `content-range` không có trong đó. Muốn đọc phải sửa máy chủ để gửi
 *      thêm `Access-Control-Expose-Headers`.
 *
 *   2. GET dải hậu tố `bytes=-66000` ("66 KB cuối").
 *      Ngã ở TypeError: Failed to fetch. Header `Range` chỉ được miễn tiền
 *      kiểm khi có dạng `bytes=<số>-<số>`; dạng hậu tố không được miễn, nên
 *      trình duyệt bắn OPTIONS trước, mà máy chủ chỉ khai
 *      `access-control-allow-headers: content-type` — không có `range`.
 *
 * Cách đang dùng: HEAD không kèm header lạ nào nên không bị tiền kiểm, còn
 * `content-length` thì NẰM TRONG danh sách an toàn của CORS nên đọc được.
 */
async function coLon(url) {
  const r = await fetch(url, { method: 'HEAD' });
  if (!r.ok) throw new Error(`Không đọc được ${url}: HTTP ${r.status}`);
  const n = Number(r.headers.get('content-length'));
  if (Number.isFinite(n) && n > 22) return n;
  throw new Error(
    'Máy chủ không cho biết kích thước file zip ' +
      '(HEAD không trả content-length đọc được)'
  );
}

/**
 * Mở zip từ xa. Trả về ĐÚNG bộ hàm như openZip() bên zip-store.js
 * (count, prefix, has, list, blob) nên chỗ gọi không phải phân biệt.
 */
async function openZipRemote(url) {
  const size = await coLon(url);

  // ---- dò EOCD trong 64 KB cuối
  const tailStart = Math.max(0, size - EOCD_SEARCH_XA);
  const tail = new DataView(await khuc(url, tailStart, size));

  let eocd = -1;
  for (let i = tail.byteLength - 22; i >= 0; i--) {
    if (tail.getUint32(i, true) === SIG_EOCD_XA) {
      eocd = i;
      break;
    }
  }
  if (eocd < 0) throw new Error('Không phải file zip hợp lệ: thiếu EOCD');

  const count = tail.getUint16(eocd + 10, true);
  const cdSize = tail.getUint32(eocd + 12, true);
  const cdOffset = tail.getUint32(eocd + 16, true);

  if (cdOffset === 0xffffffff || count === 0xffff) {
    throw new Error('Zip64 chưa hỗ trợ — nén lại bằng zip thường');
  }

  // ---- kéo cả bảng mục lục một lượt
  const cdBuf = await khuc(url, cdOffset, cdOffset + cdSize);
  const cd = new DataView(cdBuf);
  const utf8 = new TextDecoder('utf-8');

  const entries = new Map();
  let p = 0;
  for (let i = 0; i < count; i++) {
    if (cd.getUint32(p, true) !== SIG_CD_XA) break;

    const method = cd.getUint16(p + 10, true);
    const compSize = cd.getUint32(p + 20, true);
    const rawSize = cd.getUint32(p + 24, true);
    const nameLen = cd.getUint16(p + 28, true);
    const extraLen = cd.getUint16(p + 30, true);
    const cmtLen = cd.getUint16(p + 32, true);
    const localAt = cd.getUint32(p + 42, true);

    const name = utf8.decode(new Uint8Array(cdBuf, p + 46, nameLen));
    p += 46 + nameLen + extraLen + cmtLen;

    if (name.endsWith('/')) continue;
    if (name.startsWith('__MACOSX/') || name.endsWith('.DS_Store')) continue;

    entries.set(name, { method, compSize, rawSize, localAt });
  }

  if (entries.size === 0) throw new Error('Zip rỗng hoặc không đọc được mục nào');

  /* Tiền tố thư mục trong zip — tự dò như bản đọc đĩa. Zip hiện dùng nén cả
     thư mục gốc nên mục có dạng "muonlinejs-master/public/game-assets/…". */
  const MOC = 'game-assets/World1/EncTerrain1.map';
  let prefix = '';
  for (const name of entries.keys()) {
    if (name === MOC) { prefix = ''; break; }
    if (name.endsWith('/' + MOC)) {
      prefix = name.slice(0, name.length - MOC.length);
      break;
    }
  }

  return {
    get count() {
      return entries.size;
    },
    get prefix() {
      return prefix;
    },
    /** Cho biết đây là zip đọc từ xa — lớp trên dùng để ghi nhật ký cho đúng. */
    get tuXa() {
      return true;
    },
    get diaChi() {
      return url;
    },

    has(logicalPath) {
      return entries.has(prefix + logicalPath);
    },

    list() {
      const out = [];
      for (const k of entries.keys()) {
        out.push(prefix && k.startsWith(prefix) ? k.slice(prefix.length) : k);
      }
      return out;
    },

    async blob(logicalPath) {
      const e = entries.get(prefix + logicalPath);
      if (!e) return null;

      /* Một yêu cầu lấy cả đầu file lẫn dữ liệu. Trường extra ở đầu file có
         thể khác trường extra trong bảng mục lục, nên phải đọc đầu file mới
         biết dữ liệu bắt đầu ở đâu — nhưng xin dư sẵn thì khỏi đi hai lượt. */
      const tu = e.localAt;
      const den = Math.min(size, tu + 30 + DU_DAU + e.compSize);
      const buf = await khuc(url, tu, den);
      const dv = new DataView(buf);

      if (dv.getUint32(0, true) !== SIG_LOCAL_XA) {
        throw new Error(`Hỏng cấu trúc zip ở ${logicalPath}`);
      }
      const bo = 30 + dv.getUint16(26, true) + dv.getUint16(28, true);

      /* Trường extra dài hơn mức xin dư thì khúc vừa lấy bị thiếu đuôi — hiếm,
         nhưng cứ xin lại đúng khúc còn hơn trả ra file cụt. */
      let du = buf.slice(bo, bo + e.compSize);
      if (du.byteLength < e.compSize) {
        du = await khuc(url, tu + bo, tu + bo + e.compSize);
      }

      const raw = new Blob([du]);
      if (e.method === 0) return raw;
      if (e.method !== 8) {
        throw new Error(`Kiểu nén ${e.method} chưa hỗ trợ (${logicalPath})`);
      }
      const out = raw.stream().pipeThrough(new DecompressionStream('deflate-raw'));
      return await new Response(out).blob();
    },
  };
}

/**
 * Địa chỉ zip từ xa, đọc từ nơi NGƯỜI DÙNG NHÌN THẤY ĐƯỢC.
 *
 * Thứ tự: ?zipurl= trên URL → <meta name="mu-zip-url"> → window.MU_ZIP_URL.
 * Không có nguồn nào khác, không nhớ ngầm trong trình duyệt. Không khai thì
 * hàm trả null và game chạy hoàn toàn cục bộ như cũ.
 */
function diaChiZipTuXa() {
  try {
    const q = new URLSearchParams(location.search).get('zipurl');
    if (q) return q;
  } catch {
    /* file:// không có search hợp lệ */
  }
  const meta = document.querySelector('meta[name="mu-zip-url"]');
  const m = meta?.getAttribute('content')?.trim();
  if (m) return m;
  const g = typeof window !== 'undefined' ? window.MU_ZIP_URL : null;
  return g || null;
}

/* js/zip-net.js */
// Phục vụ asset trong zip cho ba đường nạp của trình duyệt.
//
// VÌ SAO CẦN: engine hỏi đường dẫn theo kiểu ĐỒNG BỘ — resolveUrlToDataFolder()
// phải trả về một chuỗi ngay lập tức — mà bung một mục trong zip lại là việc
// BẤT ĐỒNG BỘ. Bản trước giải quyết bằng cách bung sẵn cả bản đồ ra blob URL,
// nhưng cách ấy chỉ đủ cho World*/Object*: model nhân vật (60 MB), quái
// (144 MB), vật phẩm (28 MB), NPC (27 MB), âm thanh (27 MB) và decoder đều nạp
// theo nhu cầu lúc chạy, không biết trước file nào để mà bung sẵn. Bung hết là
// 532 MB — Safari giết tab.
//
// CÁCH LÀM: đường dẫn trong zip được trả về dưới dạng một URL "giả" cùng nguồn
//
//     http://<trang>/__muzip/game-assets/Player/ArmorMale01.glb
//
// rồi chặn đúng ba chỗ trình duyệt đi lấy dữ liệu — fetch(), XMLHttpRequest và
// thuộc tính .src của <img> — để đọc thẳng từ zip. URL giả không bao giờ ra tới
// mạng: nó bị chặn từ trước.
//
// Nhờ đó mọi asset đều chạy được qua zip mà không phải bung sẵn thứ gì, và
// cũng không phải sửa engine thêm lần nào nữa.
//
// GIỚI HẠN ĐÃ BIẾT: url() trong CSS thì KHÔNG chặn được — trình duyệt tự đi lấy,
// không qua fetch/XHR/Image. Chỗ nào cần đưa ảnh vào CSS (nền radar, bản đồ to)
// phải xin blob URL thật bằng MU_ASSETS.blobUrl(), xem js/asset-paths.js.

const MARK = '__muzip/';

/** Đường dẫn logic → URL giả cùng nguồn. */
function zipUrl(base, logicalPath) {
  const enc = logicalPath
    .replace(/^\/+/, '')
    .split('/')
    .map(encodeURIComponent)
    .join('/');
  return base + MARK + enc;
}

/** URL giả → đường dẫn logic, hoặc null nếu không phải URL của zip. */
function zipPathOf(url) {
  const i = url.indexOf(MARK);
  if (i < 0) return null;
  let p = url.slice(i + MARK.length);
  // Cắt tham số và neo. Dấu # trong TÊN FILE đã được mã hoá thành %23 từ
  // trước (Babylon tự làm trong CleanUrl), nên dấu # còn sót lại là neo thật.
  const q = p.search(/[?#]/);
  if (q >= 0) p = p.slice(0, q);
  try {
    return decodeURIComponent(p);
  } catch {
    return p;
  }
}

const MIME = {
  glb: 'model/gltf-binary',
  gltf: 'model/gltf+json',
  jpg: 'image/jpeg',
  jpeg: 'image/jpeg',
  png: 'image/png',
  tga: 'image/x-tga',
  ogg: 'audio/ogg',
  mp3: 'audio/mpeg',
  wasm: 'application/wasm',
  js: 'text/javascript',
  json: 'application/json',
  woff2: 'font/woff2',
  woff: 'font/woff',
  ttf: 'font/ttf',
};

function mimeOf(path) {
  const ext = path.slice(path.lastIndexOf('.') + 1).toLowerCase();
  return MIME[ext] || 'application/octet-stream';
}

/**
 * Cài cả ba lớp chặn.
 *
 * @param read     (path) => Promise<Blob|null> — đọc một mục trong zip.
 * @param fallback (path) => string — URL dự phòng khi zip không có mục đó.
 */
function installZipNet(read, fallback) {
  installFetch(read, fallback);
  installXhr(read, fallback);
  installImage(read, fallback);
}

// ------------------------------------------------------------------- fetch
function installFetch(read, fallback) {
  const original = globalThis.fetch.bind(globalThis);

  globalThis.fetch = async (input, init) => {
    const url = typeof input === 'string' ? input : input?.url;
    const path = typeof url === 'string' ? zipPathOf(url) : null;
    if (path === null) return original(input, init);

    const blob = await read(path);
    if (!blob) return original(fallback(path), init);

    return new Response(blob, {
      status: 200,
      statusText: 'OK',
      headers: {
        'Content-Type': blob.type || mimeOf(path),
        'Content-Length': String(blob.size),
      },
    });
  };
}

// --------------------------------------------------------------------- XHR
//
// Không dựng lại XHR giả: chỉ HOÃN lời gọi open() thật cho tới lúc send(), rồi
// mở lại trên một blob URL. Nhờ vậy readyState, status, response, các sự kiện
// progress/loadend/readystatechange đều là hàng thật của trình duyệt — đúng
// những thứ Babylon dựa vào trong RequestFile().
//
// Được phép hoãn vì giữa open() và send() Babylon chỉ đặt responseType và gắn
// sự kiện; cả hai đều hợp lệ khi XHR còn ở trạng thái UNSENT.
function installXhr(read, fallback) {
  const Native = globalThis.XMLHttpRequest;

  class MuZipXhr extends Native {
    open(method, url, ...rest) {
      const path = typeof url === 'string' ? zipPathOf(url) : null;
      if (path === null) {
        this.__muPath = null;
        return super.open(method, url, ...rest);
      }
      this.__muPath = path;
      this.__muMethod = method || 'GET';
      this.__muHeaders = [];
      this.__muAborted = false;
    }

    setRequestHeader(name, value) {
      // Chưa open() thật thì chưa đặt được, giữ lại đặt sau.
      if (this.__muPath) {
        this.__muHeaders.push([name, value]);
        return;
      }
      return super.setRequestHeader(name, value);
    }

    abort() {
      this.__muAborted = true;
      return super.abort();
    }

    send(body) {
      const path = this.__muPath;
      if (!path) return super.send(body);

      read(path)
        .then(blob => {
          if (this.__muAborted) return;

          const url = blob ? URL.createObjectURL(blob) : fallback(path);
          if (blob) {
            this.addEventListener('loadend', () => URL.revokeObjectURL(url), {
              once: true,
            });
          }

          super.open(this.__muMethod, url, true);
          for (const [n, v] of this.__muHeaders) {
            try {
              super.setRequestHeader(n, v);
            } catch {
              /* blob URL không nhận header — bỏ qua */
            }
          }
          super.send();
        })
        .catch(() => {
          if (this.__muAborted) return;
          super.open(this.__muMethod, fallback(path), true);
          super.send();
        });
    }
  }

  globalThis.XMLHttpRequest = MuZipXhr;
}

// ------------------------------------------------------------------- <img>
//
// Babylon nạp texture bằng `new Image(); img.src = url` (Tools.LoadImage), còn
// giao diện thì gắn icon vật phẩm y hệt. Bọc chính thuộc tính .src: thấy URL
// của zip thì chưa gán vội, bung xong mới gán blob URL thật vào.
/* Đệm blob URL cho <img>, khoá theo đường dẫn logic.
   -------------------------------------------------------------------------
   LỖI ĐÃ SỬA: bản trước cấp một blob URL mới cho MỖI thẻ <img> rồi thu hồi
   ngay trong sự kiện 'load'. Ảnh đã hiện thì không sao, nhưng .src của thẻ vẫn
   trỏ vào URL đã chết — nên khi trình duyệt cần lấy LẠI (đóng rồi mở lại một
   panel là thẻ bị gỡ ra gắn vào, trình duyệt đi lấy lại từ đầu) thì hỏng với
   net::ERR_FILE_NOT_FOUND. Đo được đúng một lần trong lượt soát toàn bộ.

   Cách sửa: một đường dẫn dùng chung MỘT url, giữ sống để lần lấy lại còn
   thấy. Có trần LRU nên không hoá rò bộ nhớ — texture Babylon nạp một lần rồi
   đẩy lên GPU, nguội dần và bị đẩy ra; icon giao diện dùng đi dùng lại nên
   luôn nằm trong đệm. Trần 400 đủ rộng: túi 64 ô + 12 ô trang bị + 5 ô thanh
   bar mới là 81 icon. */
const TRAN_ANH = 400;
const khoAnh = new Map();

function urlAnh(path, blob) {
  const co = khoAnh.get(path);
  if (co) {
    // Đụng lại thì đẩy xuống cuối hàng — Map giữ đúng thứ tự chèn nên xoá rồi
    // đặt lại là cách gọn nhất để có LRU.
    khoAnh.delete(path);
    khoAnh.set(path, co);
    return co;
  }
  const url = URL.createObjectURL(blob);
  khoAnh.set(path, url);
  while (khoAnh.size > TRAN_ANH) {
    const cu = khoAnh.keys().next().value;
    URL.revokeObjectURL(khoAnh.get(cu));
    khoAnh.delete(cu);
  }
  return url;
}

function installImage(read, fallback) {
  const proto = HTMLImageElement.prototype;
  const desc = Object.getOwnPropertyDescriptor(proto, 'src');
  if (!desc || !desc.set) return;

  /* React (giao diện gốc của engine) gắn ảnh bằng setAttribute('src', …) chứ
     không gán thuộc tính, nên lớp bọc dưới đây bị lọt. Đây đúng là chỗ bốn
     icon bình thuốc item_14_*.png vẫn chui ra mạng ở lần chạy thử trước.
     Đẩy setAttribute về đúng đường thuộc tính là xong. */
  const nativeSetAttr = proto.setAttribute;
  proto.setAttribute = function (name, value) {
    if (String(name).toLowerCase() === 'src') {
      this.src = value;
      return;
    }
    return nativeSetAttr.call(this, name, value);
  };

  Object.defineProperty(proto, 'src', {
    configurable: true,
    enumerable: desc.enumerable,

    // Trả lại đúng URL người gọi đã đặt, không phải blob URL nội bộ — Babylon
    // đọc lại .src để in thông báo lỗi.
    get() {
      return this.__muSrc ?? desc.get.call(this);
    },

    set(value) {
      const path = typeof value === 'string' ? zipPathOf(value) : null;
      if (path === null) {
        this.__muSrc = undefined;
        desc.set.call(this, value);
        return;
      }

      this.__muSrc = value;
      // Gán src nhiều lần liên tiếp (onerror lùi về icon gốc) thì chỉ lần cuối
      // được tính.
      const tem = (this.__muTem = (this.__muTem | 0) + 1);

      read(path)
        .then(blob => {
          if (this.__muTem !== tem) return;
          if (!blob) {
            desc.set.call(this, fallback(path));
            return;
          }
          desc.set.call(this, urlAnh(path, blob));
        })
        .catch(() => {
          if (this.__muTem === tem) desc.set.call(this, fallback(path));
        });
    },
  });
}

/* js/asset-paths.js */
// Bộ phân giải đường dẫn asset cho MU Mobile.
//
// CHỈ DÙNG ĐƯỜNG DẪN NỘI BỘ. Mọi lối ra CDN của nguồn ngoài đã cắt: không còn
// kho trên mạng ở bất cứ đâu, không còn chế độ 'cdn', không còn
// lùi ra mạng khi thiếu file. Thiếu thì GHI VÀO NHẬT KÝ GỠ LỖI để còn biết
// đường bổ sung, chứ không lặng lẽ đi mượn.
//
// Mọi asset có đúng MỘT đường dẫn logic, khớp cây public/ của bản gốc:
//   game-assets/World1/EncTerrain1.map
//   game-assets/Player/ArmorMale01.glb
//   items/item_0_0_0.png
//   js/draco_decoder_gltf.wasm
//   fonts/segoeuib.woff2
//
// BA nguồn nạp, đều nằm trong máy:
//   folder  <MU_FOLDER>/<logic>   ← public/game-assets/World1/EncTerrain1.map
//   zip     img/assets.zip — đọc thẳng trong file nén, xem js/zip-store.js
//   flat    img/<logic đã thay "/" bằng "_">  ← img/game-assets_World1_EncTerrain1.map
//
// 'folder' là MẶC ĐỊNH và đơn giản nhất: giữ nguyên cây thư mục gốc, không
// đổi tên, không nén. Dùng khi chạy từ máy tính hoặc từ một máy chủ tĩnh.
//
// 'zip' sinh ra vì JSAnywhere trên iOS chỉ cho nạp TỪNG file vào img/, không
// nạp cả thư mục — 12 nghìn file thì chịu, một file zip thì xong.
//
// 'flat' là lối thoát cuối: iOS không cho thư mục con thì đổ hết vào img/ với
// tên đã dẹp phẳng.



const FLAT_BASE = 'img/';

/* Gốc cây thư mục asset ở chế độ 'folder'. Đổi được từ ngoài mà không phải
   dựng lại: đặt window.MU_FOLDER trước khi nạp script.js, hoặc thêm
   ?folder=... trên URL. Luôn kết thúc bằng dấu '/'. */
const FOLDER_MAC_DINH = 'public/';

function goc() {
  let v = null;
  let tu = 'mặc định';
  try {
    v = new URLSearchParams(location.search).get('folder');
    if (v) tu = '?folder=';
  } catch {
    /* file:// không có search hợp lệ */
  }
  if (!v && typeof window !== 'undefined' && typeof window.MU_FOLDER === 'string') {
    v = window.MU_FOLDER;
    tu = 'window.MU_FOLDER';
  }
  if (!v && typeof document !== 'undefined') {
    // Thẻ <meta name="mu-folder"> trong index.html — chỗ sửa tên thư mục mà
    // KHÔNG phải dựng lại script.js và cũng không cần mã nội tuyến nào.
    const m = document.querySelector('meta[name="mu-folder"]');
    if (m?.content) {
      v = m.content;
      tu = '<meta name="mu-folder">';
    }
  }
  v = (v || FOLDER_MAC_DINH).trim();
  if (!v.endsWith('/')) v += '/';
  GOC_TU = tu;
  return v;
}

let GOC_TU = 'mặc định';


/** Nơi tìm file nén. Đường dẫn cố định vì JSAnywhere buộc nạp vào img/. */
const ZIP_PATH = 'img/assets.zip';

/** Đường dẫn logic → tên phẳng dưới img/. */
function flatName(logicalPath) {
  return logicalPath.replace(/^\/+/, '').replace(/\//g, '_');
}

function urlFor(logicalPath) {
  return FLAT_BASE + flatName(logicalPath.replace(/^\/+/, ''));
}

/** Chế độ người dùng ép buộc, nếu có. */
const CHE_DO = ['folder', 'zip', 'flat'];

/* Chế độ đến từ đâu — CHỈ hai nguồn, cả hai đều NHÌN THẤY ĐƯỢC:
     1. ?assets=... trên URL           (tạm, cho một lần mở)
     2. <meta name="mu-source">        (cố định, sửa thẳng trong index.html)

   KHÔNG dùng localStorage nữa, và đây là chủ ý. Trạng thái nhớ ngầm trong
   trình duyệt là thứ đè lên mặc định mà không ai nhìn thấy, không sửa được
   bằng cách mở file ra đọc — đúng kiểu "khoá ngầm" cần tránh. Muốn đổi chế
   độ thì sửa một dòng trong index.html, đọc là biết. */
function forcedMode() {
  return forcedModeTuUrl() ?? forcedModeTuMeta();
}

/** Chế độ ép bằng ?assets= trên URL — ý muốn tức thời, mạnh nhất. */
function forcedModeTuUrl() {
  try {
    const q = new URLSearchParams(location.search).get('assets');
    if (CHE_DO.includes(q)) return q;
  } catch {
    /* file:// không có search hợp lệ — bỏ qua */
  }
  return null;
}

/** Chế độ ép bằng <meta name="mu-source"> — mặc định ghi sẵn trong trang. */
function forcedModeTuMeta() {
  if (typeof document !== 'undefined') {
    const m = document.querySelector('meta[name="mu-source"]');
    if (m && CHE_DO.includes(m.content)) return m.content;
  }
  return null;
}

const MU_ASSETS = {
  FLAT_BASE,

  /** 'folder' | 'zip' | 'flat' — chốt một lần khi boot, xem probe(). */
  mode: 'folder',

  /** Gốc cây thư mục ở chế độ 'folder'. Tính một lần lúc nạp. */
  FOLDER_BASE: goc(),

  /**
   * Những đường dẫn logic mà kho KHÔNG CÓ.
   * Trước đây chỗ thiếu được lặng lẽ lấy từ CDN ngoài nên chẳng ai biết kho
   * của mình hụt gì. Nay ghi lại hết, hiện ra trong nhật ký gỡ lỗi.
   */
  thieu: new Set(),

  /** Kho zip đã mở, nếu chạy ở chế độ 'zip'. */
  zip: null,

  /**
   * Đệm nội dung đã bung: đường-dẫn-logic → Blob.
   *
   * Đệm BLOB chứ không đệm blob URL. Đã thử đệm URL và hỏng: blob URL không có
   * phần mở rộng, mà SceneLoader của Babylon chọn trình đọc THEO ĐUÔI FILE —
   * mọi .glb đều báo "Unable to find a plugin to load ... files". URL giả
   * __muzip/ giữ nguyên đuôi nên không dính lỗi đó, còn đệm blob thì giúp
   * nạp trước cả bản đồ vẫn có tác dụng: mỗi mục chỉ bung một lần.
   */
  cache: new Map(),

  /** Blob URL thật đã cấp cho CSS (nền radar, bản đồ to, phông chữ). */
  urls: new Map(),

  /** true khi mode do người dùng ép, không phải do thăm dò. */
  forced: false,

  /** Gốc URL giả của zip — thư mục chứa trang, tính một lần. */
  get zipBase() {
    if (!this._zipBase) {
      let b = '';
      try {
        b = new URL('.', document.baseURI).href;
      } catch {
        b = '';
      }
      this._zipBase = b;
    }
    return this._zipBase;
  },

  /** Phân giải một đường dẫn logic đầy đủ. ĐỒNG BỘ — engine đòi vậy. */
  resolve(logicalPath) {
    // Sửa lệch hoa-thường TRƯỚC mọi thứ: cả ba chế độ (folder, zip, flat) đều
    // phân biệt hoa thường, mà bảng vật phẩm của MU thì không. Xem
    // suaHoaThuong() trong js/asset-manifest.js.
    const clean = suaHoaThuong(logicalPath.replace(/^\/+/, ''));
    // Chế độ thư mục: đường dẫn logic CHÍNH LÀ đường dẫn trên đĩa, chỉ thêm
    // gốc vào trước. Không đổi tên, không chặn, không bung — nhẹ nhất.
    if (this.mode === 'folder') return this.FOLDER_BASE + clean;
    if (this.mode === 'zip' && this.zip) {
      // URL giả, giữ nguyên đuôi file; js/zip-net.js chặn lại và đọc từ zip.
      if (this.zip.has(clean)) return zipUrl(this.zipBase, clean);
      // Zip không có mục này thì lùi về img/ phẳng — vẫn trong máy. Ghi lại để
      // còn biết kho hụt gì.
      this.ghiThieu(clean);
    }
    return urlFor(clean);
  },

  /**
   * Blob URL THẬT của một mục trong zip, có nhớ lại.
   *
   * Chỉ dùng cho chỗ nào bắt buộc phải có URL thật: url() trong CSS không đi
   * qua fetch/XHR/Image nên lớp chặn không với tới (nền radar, bản đồ to,
   * @font-face). Mọi chỗ khác cứ dùng resolve() cho nhẹ bộ nhớ.
   */
  async blobUrl(logicalPath) {
    const clean = logicalPath.replace(/^\/+/, '');
    const co = this.urls.get(clean);
    if (co) return co;
    if (this.mode !== 'zip' || !this.zip) return this.resolve(clean);

    const b = await this.readZip(clean).catch(() => null);
    if (!b) {
      this.ghiThieu(clean);
      return urlFor(clean);
    }

    const u = URL.createObjectURL(b);
    this.urls.set(clean, u);
    return u;
  },

  /**
   * Đọc một mục trong zip ra Blob — lớp chặn ở js/zip-net.js gọi hàm này.
   * Có trong đệm thì lấy đệm, không thì bung (KHÔNG tự nhét vào đệm: chỉ
   * preloadMap mới được nhét, để còn biết lúc nào thả ra).
   */
  async readZip(logicalPath) {
    if (!this.zip) return null;
    const c = this.cache.get(logicalPath);
    if (c) return c;
    return this.zip.blob(logicalPath);
  },

  /** Ghi nhận một đường dẫn kho không có. Mỗi đường dẫn chỉ kêu một lần. */
  ghiThieu(logicalPath) {
    if (this.thieu.has(logicalPath)) return;
    this.thieu.add(logicalPath);
    DBG.warn('kho thiếu', logicalPath);
  },

  /**
   * Engine gọi hàm này với đường dẫn tương đối gốc game-assets
   * ('World1/EncTerrain1.map', 'Player/ArmorMale01.glb', 'Sound/death1.ogg').
   * Chèn vào chỗ resolveUrlToDataFolder() của bundle.
   */
  game(relPath) {
    if (
      relPath.startsWith('http://') ||
      relPath.startsWith('https://') ||
      relPath.startsWith('base64:') ||
      relPath.startsWith('data:') ||
      relPath.startsWith('blob:')
    ) {
      return relPath;
    }
    return this.resolve('game-assets/' + relPath.replace(/^[./]+/, ''));
  },

  /* Ba tiền tố dưới đây được nối thẳng với tên file ở nơi khác, nên phải là
     CHUỖI, không thể là blob URL của từng mục. Chế độ zip dùng được vì URL giả
     cũng chỉ là một tiền tố — lớp chặn tự bung khi có ai đi lấy. */

  /** Icon vật phẩm — nơi gọi nối tiếp 'item_<nhóm>_<số>_<cấp>.png'. */
  get itemsBase() {
    if (this.mode === 'folder') return this.FOLDER_BASE + 'items/';
    if (this.mode === 'zip' && this.zip) return zipUrl(this.zipBase, 'items/');
    return FLAT_BASE + 'items_';
  },

  /** Thư mục decoder của Babylon (draco / ktx2 / basis).
      Bộ asset này KHÔNG dùng tới: đã dò cả 2.443 file .glb, không file nào khai
      KHR_draco_mesh_compression, KHR_texture_basisu hay EXT_meshopt. Vẫn trỏ
      đúng chỗ để bản khác thay asset vào là chạy, khỏi phải sửa. */
  get decoderBase() {
    if (this.mode === 'folder') return this.FOLDER_BASE + 'js/';
    if (this.mode === 'zip' && this.zip) return zipUrl(this.zipBase, 'js/');
    return FLAT_BASE + 'js_';
  },

  /** Nguồn @font-face cho Segoe UI của MU. */
  get fontBase() {
    if (this.mode === 'folder') return this.FOLDER_BASE + 'fonts/';
    if (this.mode === 'zip' && this.zip) return zipUrl(this.zipBase, 'fonts/');
    return FLAT_BASE + 'fonts_';
  },

  /**
   * Chốt nguồn nạp — ĐỒNG BỘ, không dò mạng.
   *
   * Trang chạy bằng script cổ điển (để mở được trên iOS qua file://), giữa các
   * thẻ <script> không chờ await được, mà engine cần biết nguồn ngay lúc khởi
   * động. Thứ tự: ?assets= trên URL → <meta name="mu-source"> →
   * window.MU_SOURCE → mặc định 'folder'. Không nguồn nào đi ra mạng, và
   * không nguồn nào nằm ngầm trong trình duyệt.
   */
  probe() {
    // Zip đã mở thì giữ nguyên. bootEngine() gọi probe() SAU openZipSource(),
    // không chặn ở đây là chế độ zip bị ghi đè mất ngay khi vừa mở xong.
    const ep = forcedMode();

    /* Zip ĐÃ MỞ được thì giữ nguyên, trừ khi ?assets= trên URL bảo khác.
       Thẻ <meta name="mu-source"> KHÔNG lật được: nó ghi "folder" sẵn trong
       mọi bản dựng, mà zip chỉ mở khi người dùng tự khai địa chỉ ở
       <meta name="mu-zip-url"> — lời khai sau cụ thể hơn, phải thắng.

       Lỗi đã gặp: mở zip từ xa xong, đọc được 12.209 mục, rồi probe() chạy
       sau và lật về "folder", thế là cả kho vừa mở thành vô dụng. */
    if (this.mode === 'zip' && this.zip) {
      const tuUrl = forcedModeTuUrl();
      if (!tuUrl || tuUrl === 'zip') return this.mode;
    }
    if (this.mode === 'zip' && this.zip && !ep) return this.mode;

    if (ep === 'flat' || ep === 'folder' || (ep === 'zip' && this.zip)) {
      this.mode = ep;
      this.forced = true;
      // Nói rõ AI ép: lẫn giữa "?assets= trên URL" và "trình duyệt nhớ từ lần
      // trước" là chỗ dễ mất cả buổi để tìm.
      let tu = '<meta name="mu-source">';
      try {
        if (new URLSearchParams(location.search).get('assets') === ep) tu = '?assets= trên URL';
      } catch {
        /* file:// */
      }
      DBG.info('nguồn', `ép bằng ${tu} → ${this.mode}`);
      return this.mode;
    }

    const g = typeof window !== 'undefined' ? window.MU_SOURCE : null;
    if (g === 'flat' || g === 'folder') {
      this.mode = g;
      this.forced = true;
      DBG.info('nguồn', `ép bằng MU_SOURCE → ${g}`);
      return this.mode;
    }

    // Không có zip thì đọc thẳng cây thư mục — đây là cách dùng thường ngày.
    this.mode = 'folder';
    DBG.info('nguồn', `mặc định → đọc thư mục "${this.FOLDER_BASE}" (đặt bởi ${GOC_TU})`);
    return this.mode;
  },

  /**
   * Thử mở img/assets.zip. Có thì chuyển sang chế độ 'zip' và trả về số mục
   * đọc được; không có thì trả 0 và giữ nguyên chế độ cũ.
   *
   * Gọi lúc khởi động, TRƯỚC khi vào thế giới — mở zip là việc bất đồng bộ nên
   * không nhét vào probe() được.
   */
  async openZipSource(fetchZip, open, path = ZIP_PATH) {
    try {
      const res = await fetchZip(path);
      if (!res.ok) {
        DBG.warn('zip', `${path} trả về HTTP ${res.status}`);
        return 0;
      }

      // .blob() chứ KHÔNG .arrayBuffer(): Safari đẩy Blob lớn xuống đĩa, còn
      // arrayBuffer là nhét thẳng 288 MB vào RAM.
      const b = await res.blob();
      DBG.info('zip', `${path} · ${(b.size / 1048576).toFixed(1)} MB, đang đọc mục lục`);
      const z = await open(b);
      this.zip = z;
      this.mode = 'zip';
      this.forced = true;
      DBG.info('zip', `đọc được ${z.count} mục · tiền tố "${z.prefix}"`);
      return z.count;
    } catch (e) {
      DBG.error('zip', `mở ${path} hỏng`, e);
      return 0;
    }
  },

};

/**
 * Trước đây chỗ này có installFetchFallback(): request hụt ở CDN thì thử lại ở
 * img/. Đã bỏ cùng với CDN — nay chỉ còn một nguồn trong máy, không còn gì để
 * lùi về. Thiếu file thì ghiThieu() ghi lại, xem nhật ký gỡ lỗi.
 */

if (typeof window !== 'undefined') window.MU_ASSETS = MU_ASSETS;

/* js/asset-loader.js */
// Lớp nạp asset theo bản đồ.
//
// Engine engine vốn đã nạp model theo nhu cầu: đi tới đâu, AssetsManager tải
// model tới đó. Module này KHÔNG thay thế cơ chế ấy — nó làm hai việc engine
// không làm:
//
//   1. Nạp trước (warm cache) toàn bộ asset của một bản đồ, kèm tiến độ, để lúc
//      bước vào không bị khựng từng model một.
//   2. Cho biết bản đồ nào cần những gì, nặng bao nhiêu, đã tải xong chưa.
//
// Bản đồ số m dùng thư mục World{m+1} (địa hình + texture) và Object{m+1}
// (vật thể trang trí) — đúng quy ước engine dựng đường dẫn.


/** Các thư mục logic mà một bản đồ cần. */
function mapFolders(mapIndex) {
  const n = mapIndex + 1;
  return [`game-assets/World${n}`, `game-assets/Object${n}`];
}

/** Danh sách { path, size } của một thư mục logic. */
function folderAssets(folder) {
  const raw = MANIFEST[folder];
  if (!raw) return [];
  return raw.split(' ').map(entry => {
    const i = entry.lastIndexOf(':');
    return { path: `${folder}/${entry.slice(0, i)}`, size: +entry.slice(i + 1) };
  });
}

/** Tổng dung lượng của một bản đồ, tính trước khi tải. */
function mapWeight(mapIndex) {
  let files = 0;
  let bytes = 0;
  for (const f of mapFolders(mapIndex)) {
    for (const a of folderAssets(f)) {
      files++;
      bytes += a.size;
    }
  }
  return { files, bytes };
}

const loaded = new Set();

/** Mục nào đã bung vào đệm cho bản đồ nào, để thả ra khi rời map. */
const cachedPerMap = new Map();

/**
 * Bung asset của một bản đồ từ file zip vào đệm.
 *
 * KHÔNG cấp blob URL ở đây. Đã thử và hỏng: blob URL không mang phần mở rộng,
 * mà SceneLoader của Babylon chọn trình đọc theo ĐUÔI FILE, nên mọi .glb đều
 * báo "Unable to find a plugin to load ... files". Đường dẫn thật sự dùng là
 * URL giả __muzip/ (giữ nguyên đuôi), do js/zip-net.js chặn lại; việc bung
 * trước ở đây chỉ để mỗi mục khỏi phải giải nén lại lúc đang chơi.
 *
 * Bung song song có giới hạn. Bản đầu bung tuần tự và ĐO ĐƯỢC là quá chậm:
 * mỗi `await` nhường lại cho vòng lặp sự kiện, mà vòng lặp ấy đang bận vẽ cảnh,
 * nên mỗi file phải chờ trọn một khung hình — 1,5 file/giây, 173 file của Devias
 * mất hơn 70 giây. DecompressionStream vốn chạy ngoài luồng chính nên mở vài
 * luồng cùng lúc là lấp được đúng chỗ chờ đó.
 */
async function extractMapFromZip(mapIndex, queue, onProgress, concurrency = 6) {
  const zip = MU_ASSETS.zip;
  const total = queue.length;
  let next = 0;
  let done = 0;
  let bytes = 0;
  let failed = 0;
  const mine = [];

  // Báo tiến độ dè chừng: gọi mỗi file là mỗi file một lần dựng lại thanh
  // tiến độ, đúng thứ vừa làm chậm vòng bung.
  let baoLuc = 0;
  const bao = path => {
    const gio = performance.now();
    if (done === total || gio - baoLuc > 80) {
      baoLuc = gio;
      onProgress?.(done, total, path);
    }
  };

  async function tho() {
    for (;;) {
      const i = next++;
      if (i >= total) return;
      const a = queue[i];
      try {
        const blob = MU_ASSETS.cache.get(a.path) || (await zip.blob(a.path));
        if (!blob) {
          failed++;
        } else {
          MU_ASSETS.cache.set(a.path, blob);
          mine.push(a.path);
          bytes += blob.size;
        }
      } catch {
        failed++;
      }
      done++;
      bao(a.path);
    }
  }

  await Promise.all(Array.from({ length: concurrency }, tho));

  cachedPerMap.set(mapIndex, mine);
  if (!failed) loaded.add(mapIndex);
  return { files: done, bytes, failed, skipped: false };
}

/**
 * Thả phần đã bung của một bản đồ. Không gọi thì mỗi lần dịch chuyển lại giữ
 * thêm vài trăm MB.
 */
function releaseMap(mapIndex) {
  const list = cachedPerMap.get(mapIndex);
  if (!list) return 0;
  for (const path of list) {
    MU_ASSETS.cache.delete(path);
    // Nền radar / bản đồ to có cấp blob URL thật, thu hồi luôn kẻo rò.
    const u = MU_ASSETS.urls.get(path);
    if (u) {
      URL.revokeObjectURL(u);
      MU_ASSETS.urls.delete(path);
    }
  }
  cachedPerMap.delete(mapIndex);
  loaded.delete(mapIndex);
  return list.length;
}

/**
 * Nạp trước asset của một bản đồ.
 * Trả về { files, bytes, failed, skipped }.
 *
 * Chế độ zip thì bung từ file nén ra blob URL; hai chế độ còn lại thì tải về
 * cache trình duyệt. Tải song song có giới hạn: nhiều luồng quá thì trên 4G
 * điện thoại các request tranh băng thông và cái nào cũng chậm.
 */
async function preloadMap(mapIndex, { concurrency = 6, onProgress } = {}) {
  if (loaded.has(mapIndex)) {
    const w = mapWeight(mapIndex);
    return { ...w, failed: 0, skipped: true };
  }

  const queue = mapFolders(mapIndex).flatMap(folderAssets);

  if (MU_ASSETS.mode === 'zip' && MU_ASSETS.zip) {
    return extractMapFromZip(mapIndex, queue, onProgress, concurrency);
  }

  const total = queue.length;
  let done = 0;
  let bytes = 0;
  let failed = 0;

  async function worker() {
    for (;;) {
      const a = queue.pop();
      if (!a) return;
      try {
        const res = await fetch(MU_ASSETS.resolve(a.path), { cache: 'force-cache' });
        if (!res.ok) throw new Error(String(res.status));
        await res.arrayBuffer();
        bytes += a.size;
      } catch {
        failed++;
      }
      done++;
      onProgress?.(done, total, a.path);
    }
  }

  await Promise.all(Array.from({ length: concurrency }, worker));
  if (!failed) loaded.add(mapIndex);
  return { files: done, bytes, failed, skipped: false };
}

/** Bản đồ nào đã nạp trước xong. */
function preloadedMaps() {
  return [...loaded];
}

