/**
 * Bảy bậc màu nền ô theo cấp cường hoá, dùng chung thang với normalizeItemLvl()
 * ở trên (gộp +13 và +15 thành một bậc). Trả về 1..7.
 */
function itemTier(lvl) {
  const n = lvl ?? 0;
  if (n < 3) return 1;
  if (n < 5) return 2;
  if (n < 7) return 3;
  if (n < 9) return 4;
  if (n < 11) return 5;
  if (n < 13) return 6;
  return 7;
}

